output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_into_single_file",
    "text": "Agents must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_before_narrow_aisle",
    "text": "At the mouth of a narrow shelf aisle, an agent with a cart must not push the cart north into the aisle.",
    "abstraction": {
      "state_properties": {
        "leftAisleMouth": "at(3,3)",
        "middleAisleMouth": "at(6,3)",
        "narrowAisleMouth": {
          "or": [
            "leftAisleMouth",
            "middleAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrowAisleMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "When an agent parks a cart to enter a narrow aisle, they are obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "leftAisleMouth": "at(3,3)",
        "middleAisleMouth": "at(6,3)",
        "narrowAisleMouth": {
          "or": [
            "leftAisleMouth",
            "middleAisleMouth"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "no_cartless_wandering",
    "text": "Except at the entrance/cart bay or while using a single-file shelf aisle, agents should not wander around the store without their cart.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "permittedCartlessArea": {
          "or": [
            "entranceOrCartBay",
            "singleFileAisle",
            "narrowAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "permittedCartlessArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions from ordinary wide aisles must be done with a cart, while hand-carrying is allowed only inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfServicePoint",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_traffic_one_way_no_west",
    "text": "When pushing a cart, agents must follow one-way circulation and never travel west.",
    "abstraction": {
      "state_properties": {
        "pushingCart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushingCart",
          "W"
        ]
      }
    }
  },
  {
    "id": "take_cart_before_leaving_bay",
    "text": "After reaching the cart bay, agents are forbidden to leave it without taking a cart.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "leaveCartBayWithoutCart": {
          "pre": {
            "and": [
              "cartBay",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveCartBayWithoutCart"
    }
  }
]
